def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    weighted_pressures = []
    dangerous_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid')
        if b is not None:
            prev_bids.append(float(b))
            pressure = float(b)
            if opp.get('budget', 0) < pressure:
                pressure = float(opp.get('budget', 0))
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                pressure += 8.0
                dangerous_count += 1
            weighted_pressures.append(pressure)
        else:
            fallback = min(float(opp.get('budget', 0)), float(opp.get('daily_salary', DAILY_SALARY)) * 0.6)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                fallback += 8.0
                dangerous_count += 1
            weighted_pressures.append(fallback)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strongest_pressure = max(weighted_pressures) if weighted_pressures else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2 or no_water_days >= 2:
        urgency = 2
    elif hp <= 4 or no_water_days >= 1:
        urgency = 1

    if urgency == 2:
        target = max(DAILY_SALARY * 0.92, strongest_pressure + 2.5)
    elif scarcity == 2:
        target = max(DAILY_SALARY * 0.72, strongest_pressure + 1.5)
    elif scarcity == 1:
        target = max(DAILY_SALARY * 0.55, min(strongest_pressure + 1.0, DAILY_SALARY * 0.9))
    else:
        target = DAILY_SALARY * 0.34
        if dangerous_count >= 2:
            target = max(target, DAILY_SALARY * 0.42)
        if highest_prev < DAILY_SALARY * 0.5:
            target = max(target, highest_prev + 0.5)

    if highest_prev >= 120 and urgency == 0 and scarcity == 0:
        target = min(target, DAILY_SALARY * 0.38)

    if day >= 8 and hp <= 4:
        target = max(target, DAILY_SALARY * 0.8)

    target = min(target, budget)
    if target < 0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_ids = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_ids.append(oid)

    if not alive_ids:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids only (immediate reaction)
    yesterday_bids = []
    for oid in alive_ids:
        prev = opponents_status[oid].get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid

    # Estimate how many water units are likely to be needed to win allocation pressure.
    # Supply is in [15,25], so likely 1 or 2 water quanta (per WATER_REQ).
    # We don't know exact auction outcome, so we use a pressure-based bid.
    likely_quanta = int(supply / float(WATER_REQ))  # 15-25 => 1 or 2
    if likely_quanta < 1:
        likely_quanta = 1

    # If Cindy/Alex/Eric were bidding near high tier, opponents are willing to pay.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85
    medium_pressure = (highest_prev_bid >= DAILY_SALARY * 0.55) and not high_pressure

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Baseline bid depends on my hp.
    if hp <= 2:
        # Emergency: bid to avoid death spiral.
        bid = DAILY_SALARY * 0.9
    elif hp <= 4:
        bid = DAILY_SALARY * 0.75
    else:
        bid = DAILY_SALARY * 0.55

    # Adjust to exploit yesterday's observed willingness to pay.
    if high_pressure:
        # Secure at least one quantum; outbid only slightly unless my hp is low.
        if hp > 3:
            bid = max(bid, min(budget, highest_prev_bid + 3.0))
        else:
            bid = min(budget, max(bid, highest_prev_bid + 10.0))
    elif medium_pressure:
        # Competitive but don't burn budget.
        if hp > 3:
            bid = max(bid, min(budget, second_prev_bid + 2.0))
        else:
            bid = min(budget, max(bid, highest_prev_bid + 5.0))
    else:
        # Low pressure: bid enough to keep advantage.
        if likely_quanta >= 2:
            bid = max(bid, DAILY_SALARY * 0.6)
        else:
            bid = max(bid, DAILY_SALARY * 0.5)

    # Budget safety cap
    if budget <= 0:
        return 0.0
    bid = float(min(budget, bid))

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Estimate opponent bids from previous_trace
    estimated_bids = []
    for oid, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                # Use previous bid as estimate, maybe adjust
                estimated_bids.append(prev['bid'])
            else:
                # No history: assume low bid
                estimated_bids.append(0.0)

    # Determine urgency
    need_water = (my_hp <= 2) or (no_water_days >= 1)

    if estimated_bids:
        max_est = max(estimated_bids)
        # If we need water, we must outbid the highest estimated bid
        if need_water:
            target_bid = max_est + 1.0
            # But cap by budget
            target_bid = min(target_bid, my_budget)
            # Also ensure we can afford daily salary leftovers? Not needed.
            return target_bid
        else:
            # We have HP, can try to save budget: bid just below max_est to stay safe?
            # But if we don't need water, we can bid low or even 0
            return min(my_budget, DAILY_SALARY * 0.3)
    else:
        # No opponents alive? Should not happen often
        if need_water:
            return min(my_budget, DAILY_SALARY * 0.8)
        else:
            return min(my_budget, DAILY_SALARY * 0.2)
